  const dx = (sin * ahead + cos * side) * stride;
  const dz = (-cos * ahead + sin * side) * stride;
  if (dx && canStand(person.x + dx, person.z)) person.x += dx;
  if (dz && canStand(person.x, person.z + dz)) person.z += dz;
